$)

  $( Declare new constants. $)
  $c -us $.
  $c -s $.

  $( Declare the syntax for surreal negation. $)
  cnegs $a class -us $.

  $( Declare the syntax for surreal subtraction. $)
  csubs $a class -s $.

  ${
    $d x n $.
    $( Define surreal negation.  Definition from [Conway] p. 5.  (Contributed
       by Scott Fenton, 20-Aug-2024.) $)
    df-negs $a |- -us = norec (
      ( x e. _V , n e. _V |->
      ( ( n " ( _Right ` x ) ) |s ( n " ( _Left ` x ) ) ) ) ) $.
  $}

  ${
    $d x y $.
    $( Define surreal subtraction.  (Contributed by Scott Fenton,
       20-Aug-2024.) $)
    df-subs $a |- -s = ( x e. No , y e. No |-> ( x +s ( -us ` y ) ) ) $.
  $}

  ${
    $d x n $.
    $( Surreal negation is a function over surreals.  (Contributed by Scott
       Fenton, 20-Aug-2024.) $)
    negsfn $p |- -us Fn No $=
      ( vx vn cnegs cvv cv cright cfv cima cleft ccuts co cmpo df-negs norecfn
      ) CABDDBEZAEZFGHOPIGHJKLABMN $.
  $}

  ${
    $d x y $.
    $( Surreal subtraction is a function over pairs of surreals.  (Contributed
       by Scott Fenton, 22-Jan-2025.) $)
    subsfn $p |- -s Fn ( No X. No ) $=
      ( vx vy csur cv cnegs cfv cadds co csubs df-subs ovex fnmpoi ) ABCCADZBDE
      FZGHIABJMNGKL $.
  $}

