  ${
    lesubsd.1 $e |- ( ph -> A e. No ) $.
    lesubsd.2 $e |- ( ph -> B e. No ) $.
    lesubsd.3 $e |- ( ph -> C e. No ) $.
    $( Swap subtrahends in a surreal inequality.  (Contributed by Scott Fenton,
       29-Jan-2026.) $)
    lesubsd $p |- ( ph -> ( A <_s ( B -s C ) <-> C <_s ( B -s A ) ) ) $=
      ( cadds co csubs cles wbr csur wcel wceq npcans syl2anc addscomd 3eqtr4rd
      subscld breq2d leadds1d leadds2d 3bitr4d ) ABDHIZCDJIZDHIZKLUEBCBJIZHIZKL
      BUFKLDUHKLAUGUIUEKAUHBHIZCUIUGACMNZBMNUJCOFECBPQABUHEACBFETZRAUKDMNUGCOFG
      CDPQSUAABUFDEACDFGTGUBADUHBGULEUCUD $.
  $}

  ${
    nncansd.1 $e |- ( ph -> A e. No ) $.
    nncansd.2 $e |- ( ph -> B e. No ) $.
    $( Cancellation law for surreal subtraction.  (Contributed by Scott Fenton,
       16-Apr-2025.) $)
    nncansd $p |- ( ph -> ( A -s ( A -s B ) ) = B ) $=
      ( csubs co cadds subsubs2d csur wcel wceq pncan3s syl2anc eqtrd ) ABBCFGF
      GBCBFGHGZCABBCDDEIABJKCJKPCLDEBCMNO $.
  $}

  ${
    posdifsd.1 $e |- ( ph -> A e. No ) $.
    posdifsd.2 $e |- ( ph -> B e. No ) $.
    $( Comparison of two surreals whose difference is positive.  (Contributed
       by Scott Fenton, 10-Mar-2025.) $)
    posdifsd $p |- ( ph -> ( A <s B <-> 0s <s ( B -s A ) ) ) $=
      ( c0s csubs co clts wbr cadds csur wcel 0no subscld ltadds1d wceq addslid
      a1i syl npcans syl2anc breq12d bitr2d ) AFCBGHZIJFBKHZUEBKHZIJBCIJAFUEBFL
      MANSACBEDODPAUFBUGCIABLMZUFBQDBRTACLMUHUGCQEDCBUAUBUCUD $.
  $}

  ${
    ltsubspos.1 $e |- ( ph -> A e. No ) $.
    ltsubspos.2 $e |- ( ph -> B e. No ) $.
    $( Subtraction of a positive number decreases the sum.  (Contributed by
       Scott Fenton, 15-Apr-2025.) $)
    ltsubsposd $p |- ( ph -> ( 0s <s A <-> ( B -s A ) <s B ) ) $=
      ( c0s clts wbr csubs co csur wcel 0no a1i ltsubs2d wceq subsid1 syl bitrd
      breq2d ) AFBGHCBIJZCFIJZGHUACGHAFBCFKLAMNDEOAUBCUAGACKLUBCPECQRTS $.
  $}

  ${
    subsge0d.1 $e |- ( ph -> A e. No ) $.
    subsge0d.2 $e |- ( ph -> B e. No ) $.
    $( Non-negative subtraction.  (Contributed by Scott Fenton,
       26-May-2025.) $)
    subsge0d $p |- ( ph -> ( 0s <_s ( A -s B ) <-> B <_s A ) ) $=
      ( c0s csubs co cles wbr cadds csur wcel 0no subscld leadds1d wceq addslid
      a1i syl npcans syl2anc breq12d bitrd ) AFBCGHZIJFCKHZUECKHZIJCBIJAFUECFLM
      ANSABCDEOEPAUFCUGBIACLMZUFCQECRTABLMUHUGBQDEBCUAUBUCUD $.
  $}

  ${
    addsubs4d.1 $e |- ( ph -> A e. No ) $.
    addsubs4d.2 $e |- ( ph -> B e. No ) $.
    addsubs4d.3 $e |- ( ph -> C e. No ) $.
    addsubs4d.4 $e |- ( ph -> D e. No ) $.
    $( Rearrangement of four terms in mixed addition and subtraction.  Surreal
       version.  (Contributed by Scott Fenton, 25-Jul-2025.) $)
    addsubs4d $p |- ( ph -> ( ( A +s B ) -s ( C +s D ) ) =
     ( ( A -s C ) +s ( B -s D ) ) ) $=
      ( cadds co addsubsd oveq1d addscld subsubs4d subscld addsubsassd 3eqtr3d
      csubs ) ABCJKZDSKZESKBDSKZCJKZESKTDEJKSKUBCESKJKAUAUCESABCDFGHLMATDEABCFG
      NHIOAUBCEABDFHPGIQR $.
  $}

  ${
    ltsm1d.1 $e |- ( ph -> A e. No ) $.
    $( A surreal is greater than itself minus one.  (Contributed by Scott
       Fenton, 20-Aug-2025.) $)
    ltsm1d $p |- ( ph -> ( A -s 1s ) <s A ) $=
      ( c1s csubs co clts wbr cadds ltsp1d csur wcel 1no a1i ltsubaddsd mpbird
      ) ABDEFBGHBBDIFGHABCJABDBCDKLAMNCOP $.
  $}

  ${
    subscand.1 $e |- ( ph -> A e. No ) $.
    subscand.2 $e |- ( ph -> B e. No ) $.
    subscand.3 $e |- ( ph -> C e. No ) $.
    $( Cancellation law for surreal subtraction.  (Contributed by Scott Fenton,
       7-Nov-2025.) $)
    subscan1d $p |- ( ph -> ( ( C -s A ) = ( C -s B ) <-> A = B ) ) $=
      ( csubs wceq cnegs cfv cadds subsvald eqeq12d negscld addscan1d csur wcel
      co wb negs11 syl2anc 3bitrd ) ADBHSZDCHSZIDBJKZLSZDCJKZLSZIUFUHIZBCIZAUDU
      GUEUIADBGEMADCGFMNAUFUHDABEOACFOGPABQRCQRUJUKTEFBCUAUBUC $.

    $( Cancellation law for surreal subtraction.  (Contributed by Scott Fenton,
       7-Nov-2025.) $)
    subscan2d $p |- ( ph -> ( ( A -s C ) = ( B -s C ) <-> A = B ) ) $=
      ( csubs co wceq cnegs cfv cadds subsvald eqeq12d negscld addscan2d bitrd
      ) ABDHIZCDHIZJBDKLZMIZCUAMIZJBCJASUBTUCABDEGNACDFGNOABCUAEFADGPQR $.
  $}

  ${
    subseq0d.1 $e |- ( ph -> A e. No ) $.
    subseq0d.2 $e |- ( ph -> B e. No ) $.
    $( The difference between two surreals is zero iff they are equal.
       (Contributed by Scott Fenton, 7-Nov-2025.) $)
    subseq0d $p |- ( ph -> ( ( A -s B ) = 0s <-> A = B ) ) $=
      ( csubs co wceq c0s csur wcel subsid syl eqeq2d subscan2d bitr3d ) ABCFGZ
      CCFGZHQIHBCHARIQACJKRIHECLMNABCCDEEOP $.
  $}

$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Multiplication
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Declare a new constant. $)
  $c x.s $.

  $( Set up the syntax for surreal multiplication. $)
  cmuls $a class x.s $.

  ${
    $d z m a b c d p q r s t u v w x y $.
    $( Define surreal multiplication.  Definition from [Conway] p. 5.
       (Contributed by Scott Fenton, 4-Feb-2025.) $)
    df-muls $a |- x.s = norec2 ( ( z e. _V , m e. _V |->
    [_ ( 1st ` z ) / x ]_ [_ ( 2nd ` z ) / y ]_
    ( ( { a | E. p e. ( _Left ` x ) E. q e. ( _Left ` y )
    a = ( ( ( p m y ) +s ( x m q ) ) -s ( p m q ) ) } u.
        { b | E. r e. ( _Right ` x ) E. s e. ( _Right ` y )
    b = ( ( ( r m y ) +s ( x m s ) ) -s ( r m s ) ) } ) |s
      ( { c | E. t e. ( _Left ` x ) E. u e. ( _Right ` y )
    c = ( ( ( t m y ) +s ( x m u ) ) -s ( t m u ) ) } u.
        { d | E. v e. ( _Right ` x ) E. w e. ( _Left ` y )
    d = ( ( ( v m y ) +s ( x m w ) ) -s ( v m w ) ) } ) ) ) ) $.
  $}

  ${
    $d z m a b c d p q r s t u v w x y $.
    $( Surreal multiplication is a function over surreals.  (Contributed by
       Scott Fenton, 4-Feb-2025.) $)
    mulsfn $p |- x.s Fn ( No X. No ) $=
      ( vz vm vx vy va vp vq vb vr vs vc vt cv cfv co cadds csubs wceq wrex cab
      vu vd vv cmuls cvv c1st c2nd cleft cright cun ccuts cmpo df-muls norec2fn
      vw csb ) UDABUEUECAMZUFNDUQUGNEMFMZDMZBMZOCMZGMZUTOPOURVBUTOQORGUSUHNZSFV
      AUHNZSETHMIMZUSUTOVAJMZUTOPOVEVFUTOQORJUSUINZSIVAUINZSHTUJKMLMZUSUTOVAUAM
      ZUTOPOVIVJUTOQORUAVGSLVDSKTUBMUCMZUSUTOVAUOMZUTOPOVKVLUTOQORUOVCSUCVHSUBT
      UJUKOUPUPULCDAUOUCUALBJIGFEHKUBUMUN $.
  $}

