=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Declare new constant. $)
  $c /su $.

  $( Declare the syntax for surreal division. $)
  cdivs $a class /su $.

  ${
    $d x y z $.
    $( Define surreal division.  This is not the definition used in the
       literature, but we use it here because it is technically easier to work
       with.  (Contributed by Scott Fenton, 12-Mar-2025.) $)
    df-divs $a |- /su = ( x e. No , y e. ( No \ { 0s } ) |->
     ( iota_ z e. No ( y x.s z ) = x ) ) $.
  $}

  ${
    $d A x y z $.  $d B x y z $.
    $( The value of surreal division.  (Contributed by Scott Fenton,
       12-Mar-2025.) $)
    divsval $p |- ( ( A e. No /\ B e. No /\ B =/= 0s ) ->
     ( A /su B ) = ( iota_ x e. No ( B x.s x ) = A ) ) $=
      ( vy vz csur wcel c0s wne cdivs co cv cmuls wceq crio wa csn cdif eldifsn
      riotabidv eqeq2 oveq1 eqeq1d df-divs riotaex ovmpo sylan2br 3impb ) BFGZC
      FGZCHIZBCJKCALZMKZBNZAFOZNZUJUKPUICFHQRZGUPCFHSDEBCFUQELZULMKZDLZNZAFOUOJ
      USBNZAFOUTBNVAVBAFUTBUSUATURCNZVBUNAFVCUSUMBURCULMUBUCTDEAUDUNAFUEUFUGUH
      $.
  $}

  ${
    $d A w x z $.  $d A w y z $.  $d B w y z $.
    $( If a surreal has a reciprocal, then it has any division.  (Contributed
       by Scott Fenton, 12-Mar-2025.) $)
    norecdiv $p |- ( ( ( A e. No /\ A =/= 0s /\ B e. No ) /\
     E. x e. No ( A x.s x ) = 1s ) -> E. y e. No ( A x.s y ) = B ) $=
      ( vw vz csur wcel cv cmuls co c1s wceq wrex wa adantl eqeq1d weq cbvrexvw
      oveq2 c0s wne simprl simpl3 mulscld oveq1 simpl1 mulsassd mulslidd rspcev
      w3a 3eqtr3d syl2anc rexlimdvaa imp anbi2i 3imtr4i ) CGHZCUAUBZDGHZUKZCEIZ
      JKZLMZEGNZOCFIZJKZDMZFGNZVACAIZJKZLMZAGNZOCBIZJKZDMZBGNVAVEVIVAVDVIEGVAVB
      GHZVDOZOZVBDJKZGHCVTJKZDMZVIVSVBDVAVQVDUCZURUSUTVRUDZUEVSVCDJKZLDJKZWADVR
      WEWFMZVAVDWGVQVCLDJUFPPVSCVBDURUSUTVRUGWCWDUHVSDWDUIULVHWBFVTGVFVTMVGWADV
      FVTCJTQUJUMUNUOVMVEVAVLVDAEGAERVKVCLVJVBCJTQSUPVPVHBFGBFRVOVGDVNVFCJTQSUQ
      $.

    $( If a surreal has a reciprocal, then it has unique division.
       (Contributed by Scott Fenton, 12-Mar-2025.) $)
    noreceuw $p |- ( ( ( A e. No /\ A =/= 0s /\ B e. No ) /\
    E. x e. No ( A x.s x ) = 1s ) -> E! y e. No ( A x.s y ) = B ) $=
      ( csur wcel c0s wne w3a cv cmuls co c1s wceq wrex wa wrmo norecdiv divsmo
      wreu 3adant3 adantr reu5 sylanbrc ) CEFZCGHZDEFZIZCAJKLMNAEOZPCBJKLDNZBEO
      UJBEQZUJBETABCDRUHUKUIUEUFUKUGBCDSUAUBUJBEUCUD $.
  $}

  ${
    $d A x y $.  $d ph y $.
    recsne0.1 $e |- ( ph -> A e. No ) $.
    recsne0.2 $e |- ( ph -> E. x e. No ( A x.s x ) = 1s ) $.
    $( If a surreal has a reciprocal, then it is nonzero.  (Contributed by
       Scott Fenton, 5-Sep-2025.) $)
    recsne0 $p |- ( ph -> A =/= 0s ) $=
      ( vy cv cmuls co c1s wceq c0s wne csur wrex weq oveq2 eqeq1d wcel wa a1i
      sylib simprr 1ne0s eqnetrd adantr simprl mulsne0bd mpbid simpld rexlimddv
      cbvrexvw ) ACFGZHIZJKZCLMZFNACBGZHIZJKZBNOUOFNOEUSUOBFNBFPURUNJUQUMCHQRUL
      UBAUMNSZUOTZTZUPUMLMZVBUNLMUPVCTVBUNJLAUTUOUCJLMVBUDUAUEVBCUMACNSVADUFAUT
      UOUGUHUIUJUK $.
  $}

  ${
    $d A y $.  $d B y $.  $d C x y $.
    $( Relationship between surreal division and multiplication.  Weak version
       that does not assume reciprocals.  Later, when we prove ~ precsex , we
       can eliminate the existence hypothesis (see ~ divmuls ).  (Contributed
       by Scott Fenton, 12-Mar-2025.) $)
    divmulsw $p |- ( ( ( A e. No /\ B e. No /\ ( C e. No /\ C =/= 0s ) ) /\
     E. x e. No ( C x.s x ) = 1s ) ->
     ( ( A /su C ) = B <-> ( C x.s B ) = A ) ) $=
      ( vy csur wcel c0s wne wa w3a cv cmuls co c1s wceq wrex cdivs wb eqeq1d
      crio divsval 3expb 3adant2 adantr wreu simpl2 simp3l simp3r 3jca noreceuw
      simp1 sylan oveq2 riota2 syl2anc bitr4d ) BFGZCFGZDFGZDHIZJZKZDALMNOPAFQZ
      JZBDRNZCPZDELZMNZBPZEFUAZCPZDCMNZBPZVCVGVLSZVDURVBVOUSURUTVAVOURUTVAKVFVK
      CEBDUBTUCUDUEVEUSVJEFUFZVNVLSURUSVBVDUGVCUTVAURKVDVPVCUTVAURURUSUTVAUHURU
      SUTVAUIURUSVBULUJAEDBUKUMVJVNEFCVHCPVIVMBVHCDMUNTUOUPUQ $.
  $}

  ${
    $d C x $.
    divmulswd.1 $e |- ( ph -> A e. No ) $.
    divmulswd.2 $e |- ( ph -> B e. No ) $.
    divmulswd.3 $e |- ( ph -> C e. No ) $.
    divmulswd.4 $e |- ( ph -> C =/= 0s ) $.
    divmulswd.5 $e |- ( ph -> E. x e. No ( C x.s x ) = 1s ) $.
    $( Relationship between surreal division and multiplication.  Weak version
       that does not assume reciprocals.  (Contributed by Scott Fenton,
       12-Mar-2025.) $)
    divmulswd $p |- ( ph -> ( ( A /su C ) = B <-> ( C x.s B ) = A ) ) $=
      ( csur wcel c0s wne wa cv cmuls co c1s wceq wrex wb jca divmulsw syl31anc
      cdivs ) ACKLDKLEKLZEMNZOEBPQRSTBKUACEUFRDTEDQRCTUBFGAUGUHHIUCJBCDEUDUE $.
  $}

  ${
    $d A y $.  $d B x y $.
    $( Weak division closure law.  (Contributed by Scott Fenton,
       12-Mar-2025.) $)
    divsclw $p |- ( ( ( A e. No /\ B e. No /\ B =/= 0s ) /\
    E. x e. No ( B x.s x ) = 1s ) -> ( A /su B ) e. No ) $=
      ( vy csur wcel c0s wne w3a cv cmuls co c1s wceq wrex wa cdivs crio adantr
      divsval wreu 3anrot noreceuw sylanb riotacl syl eqeltrd ) BEFZCEFZCGHZIZC
      AJKLMNAEOZPZBCQLZCDJKLBNZDERZEUKUNUPNULDBCTSUMUODEUAZUPEFUKUIUJUHIULUQUHU
      IUJUBADCBUCUDUODEUEUFUG $.
  $}

  ${
    $d B x $.
    divsclwd.1 $e |- ( ph -> A e. No ) $.
    divsclwd.2 $e |- ( ph -> B e. No ) $.
    divsclwd.3 $e |- ( ph -> B =/= 0s ) $.
    divsclwd.4 $e |- ( ph -> E. x e. No ( B x.s x ) = 1s ) $.
    $( Weak division closure law.  (Contributed by Scott Fenton,
       12-Mar-2025.) $)
    divsclwd $p |- ( ph -> ( A /su B ) e. No ) $=
      ( csur wcel c0s wne cv cmuls co c1s wceq wrex cdivs divsclw syl31anc ) AC
      IJDIJDKLDBMNOPQBIRCDSOIJEFGHBCDTUA $.
  $}

  ${
    $d B x $.
    divscan2wd.1 $e |- ( ph -> A e. No ) $.
    divscan2wd.2 $e |- ( ph -> B e. No ) $.
    divscan2wd.3 $e |- ( ph -> B =/= 0s ) $.
    divscan2wd.4 $e |- ( ph -> E. x e. No ( B x.s x ) = 1s ) $.
    $( A weak cancellation law for surreal division.  (Contributed by Scott
       Fenton, 13-Mar-2025.) $)
    divscan2wd $p |- ( ph -> ( B x.s ( A /su B ) ) = A ) $=
      ( cdivs co wceq cmuls eqid divsclwd divmulswd mpbii ) ACDIJZQKDQLJCKQMABC
      QDEABCDEFGHNFGHOP $.

    $( A weak cancellation law for surreal division.  (Contributed by Scott
       Fenton, 13-Mar-2025.) $)
    divscan1wd $p |- ( ph -> ( ( A /su B ) x.s B ) = A ) $=
      ( cdivs co cmuls divsclwd mulscomd divscan2wd eqtrd ) ACDIJZDKJDPKJCAPDAB
      CDEFGHLFMABCDEFGHNO $.
  $}

  ${
    $d C x $.
    ltdivmulswd.1 $e |- ( ph -> A e. No ) $.
    ltdivmulswd.2 $e |- ( ph -> B e. No ) $.
    ltdivmulswd.3 $e |- ( ph -> C e. No ) $.
    ltdivmulswd.4 $e |- ( ph -> 0s <s C ) $.
    ltdivmulswd.5 $e |- ( ph -> E. x e. No ( C x.s x ) = 1s ) $.
    $( Surreal less-than relationship between division and multiplication.
       Weak version.  (Contributed by Scott Fenton, 14-Mar-2025.) $)
    ltdivmulswd $p |- ( ph -> ( ( A /su C ) <s B <-> A <s ( C x.s B ) ) ) $=
      ( cdivs co clts wbr cmuls gt0ne0sd divsclwd ltmuls2d divscan2wd breq1d
      bitrd ) ACEKLZDMNEUBOLZEDOLZMNCUDMNAUBDEABCEFHAEIPZJQGHIRAUCCUDMABCEFHUEJ
      STUA $.

    $( Surreal less-than relationship between division and multiplication.
       Weak version.  (Contributed by Scott Fenton, 14-Mar-2025.) $)
    ltdivmuls2wd $p |- ( ph -> ( ( A /su C ) <s B <-> A <s ( B x.s C ) ) ) $=
      ( cdivs co clts wbr cmuls ltdivmulswd mulscomd breq2d bitr4d ) ACEKLDMNCE
      DOLZMNCDEOLZMNABCDEFGHIJPAUATCMADEGHQRS $.

    $( Surreal less-than relationship between division and multiplication.
       Weak version.  (Contributed by Scott Fenton, 14-Mar-2025.) $)
    ltmuldivswd $p |- ( ph -> ( ( A x.s C ) <s B <-> A <s ( B /su C ) ) ) $=
      ( cdivs co clts wbr cmuls gt0ne0sd divsclwd ltmuls1d divscan1wd breq2d
      bitr2d ) ACDEKLZMNCEOLZUBEOLZMNUCDMNACUBEFABDEGHAEIPZJQHIRAUDDUCMABDEGHUE
      JSTUA $.

    $( Surreal less-than relationship between division and multiplication.
       Weak version.  (Contributed by Scott Fenton, 14-Mar-2025.) $)
    ltmuldivs2wd $p |- ( ph -> ( ( C x.s A ) <s B <-> A <s ( B /su C ) ) ) $=
      ( cmuls co clts wbr cdivs mulscomd breq1d ltmuldivswd bitr3d ) ACEKLZDMNE
      CKLZDMNCDEOLMNATUADMACEFHPQABCDEFGHIJRS $.
  $}

  ${
    $d C x $.
    divsasswd.1 $e |- ( ph -> A e. No ) $.
    divsasswd.2 $e |- ( ph -> B e. No ) $.
    divsasswd.3 $e |- ( ph -> C e. No ) $.
    divsasswd.4 $e |- ( ph -> C =/= 0s ) $.
    divsasswd.5 $e |- ( ph -> E. x e. No ( C x.s x ) = 1s ) $.
    $( An associative law for surreal division.  Weak version.  (Contributed by
       Scott Fenton, 14-Mar-2025.) $)
    divsasswd $p |- ( ph -> ( ( A x.s B ) /su C ) = ( A x.s ( B /su C ) ) ) $=
      ( cmuls co cdivs wceq divscan2wd oveq2d divsclwd muls12d mulscld 3eqtr4rd
      mulscan1d mpbid ) AECDKLZEMLZKLZECDEMLZKLZKLZNUDUGNACEUFKLZKLUCUHUEAUIDCK
      ABDEGHIJOPAECUFHFABDEGHIJQZRABUCEACDFGSZHIJOTAUDUGEABUCEUKHIJQACUFFUJSHIU
      AUB $.
  $}

  $( A surreal divided by one is itself.  (Contributed by Scott Fenton,
     13-Mar-2025.) $)
  divs1 $p |- ( A e. No -> ( A /su 1s ) = A ) $=
    ( vx csur wcel c1s cdivs co wceq cmuls mulslid wb c0s wne wa 1no pm3.2i w3a
    1ne0s cv wrex ax-mp oveq2 eqeq1d rspcev mp2an divmulsw mp3an3 anidms mpbird
    mpan2 ) ACDZAEFGAHZEAIGAHZAJUKULUMKZUKUKECDZELMZNZUNUOUPORPUKUKUQQEBSZIGZEH
    ZBCTZUNUOEEIGZEHZVAOUOVCOEJUAUTVCBECUREHUSVBEUREEIUBUCUDUEBAAEUFUJUGUHUI $.

  ${
    divs1d.1 $e |- ( ph -> A e. No ) $.
    $( A surreal divided by one is itself.  Deduction version.  (Contributed by
       Scott Fenton, 27-Feb-2026.) $)
    divs1d $p |- ( ph -> ( A /su 1s ) = A ) $=
      ( csur wcel c1s cdivs co wceq divs1 syl ) ABDEBFGHBICBJK $.
  $}

