  $( Delcare new constants. $)
  $c NN0_s NN_s $.

  $( Declare the syntax for surreal non-negative integers. $)
  cn0s $a class NN0_s $.

  $( Declare the syntax for surreal positive integers. $)
  cnns $a class NN_s $.

  $( Define the set of non-negative surreal integers.  This set behaves
     similarly to ` _om ` and ` NN0 ` , but it is a set of surreal numbers.
     Like those two sets, it satisfies the Peano axioms and is closed under
     (surreal) addition and multiplication.  Compare ~ df-nn .  (Contributed by
     Scott Fenton, 17-Mar-2025.) $)
  df-n0s $a |- NN0_s = ( rec ( ( x e. _V |-> ( x +s 1s ) ) , 0s ) " _om ) $.

  $( Define the set of positive surreal integers.  (Contributed by Scott
     Fenton, 17-Mar-2025.) $)
  df-nns $a |- NN_s = ( NN0_s \ { 0s } ) $.

  $( The set of all non-negative surreal integers exists.  This theorem avoids
     the axiom of infinity by including it as an antecedent.  (Contributed by
     Scott Fenton, 20-Feb-2025.) $)
  n0sexg $p |- ( _om e. _V -> NN0_s e. _V ) $=
    ( vf com cvv wcel cn0s cv c1s cadds co cmpt crdg cima df-n0s wfun funimaexg
    c0s rdgfun mpan eqeltrid ) BCDZEACAFGHIJZPKZBLZCAMUBNTUCCDPUAQUBBCORS $.
  $( $j usage 'n0sexg' avoids 'ax-inf' 'ax-inf2'; $)

  $( The set of all non-negative surreal integers exists.  (Contributed by
     Scott Fenton, 17-Mar-2025.) $)
  n0sex $p |- NN0_s e. _V $=
    ( com cvv wcel cn0s omex n0sexg ax-mp ) ABCDBCEFG $.

  $( The set of all positive surreal integers exists.  (Contributed by Scott
     Fenton, 17-Mar-2025.) $)
  nnsex $p |- NN_s e. _V $=
    ( cnns cn0s c0s csn cdif cvv df-nns n0sex difexi eqeltri ) ABCDZEFGBKHIJ $.

