$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Dyadic fractions
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Declare new constants. $)
  $c 2s $.
  $c ^su $.
  $c ZZ_s[1/2] $.

  $( Declare the syntax for surreal two. $)
  c2s $a class 2s $.

  $( Define surreal two.  This is the simplest number greater than one.  See
     ~ 1p1e2s for its addition version.  (Contributed by Scott Fenton,
     27-May-2025.) $)
  df-2s $a |- 2s = ( { 1s } |s (/) ) $.

  $( Declare the syntax for surreal exponentiation. $)
  cexps $a class ^su $.

  ${
    $d x y $.
    $( Define surreal exponentiation.  Compare ~ df-exp .  (Contributed by
       Scott Fenton, 27-May-2025.) $)
    df-exps $a |- ^su = ( x e. No , y e. ZZ_s |->
     if ( y = 0s , 1s ,
     if ( 0s <s y , ( seq_s 1s ( x.s , ( NN_s X. { x } ) ) ` y ) ,
     ( 1s /su ( seq_s 1s ( x.s , ( NN_s X. { x } ) ) ` ( -us ` y ) ) ) ) ) ) $.
  $}

  $( Define the syntax for the set of surreal dyadic fractions. $)
  cz12s $a class ZZ_s[1/2] $.

  ${
    $d x y z $.
    $( Define the set of dyadic rationals.  This is the set of rationals whose
       denominator is a power of two.  Later we will prove that this is
       precisely the set of surreals with a finite birthday.  (Contributed by
       Scott Fenton, 27-May-2025.) $)
    df-z12s $a |- ZZ_s[1/2] = { x |
     E. y e. ZZ_s E. z e. NN0_s x = ( y /su ( 2s ^su z ) ) } $.
  $}

  ${
    $d x y $.
    $( One plus one is two.  Surreal version.  (Contributed by Scott Fenton,
       27-May-2025.) $)
    1p1e2s $p |- ( 1s +s 1s ) = 2s $=
      ( c1s cadds co csn c0 ccuts cn0s wcel wceq 1n0s n0cut2 ax-mp df-2s eqtr4i
      c2s ) AABCZADEFCZOAGHPQIJAKLMN $.
  $}

